Execute a .NET assembly in memory without touching disk:

```csharp
// In-memory .NET assembly execution concept
// This is for educational purposes — understand the technique

using System;
using System.Reflection;
using System.IO;

public class InMemoryExecution
{
    // Method 1: Assembly.Load from byte array
    public static void LoadFromBytes(byte[] assemblyBytes)
    {
        // Load assembly directly from memory
        Assembly asm = Assembly.Load(assemblyBytes);

        // Find and invoke the entry point
        MethodInfo entry = asm.EntryPoint;
        if (entry != null)
        {
            entry.Invoke(null, null);
        }
    }

    // Method 2: Load from memory stream
    public static void LoadFromStream(byte[] assemblyBytes)
    {
        using (var ms = new MemoryStream(assemblyBytes))
        {
            // BinaryReader for raw bytes
            // Assembly.Load handles the rest
            var asm = Assembly.Load(assemblyBytes);
            var entry = asm.EntryPoint;
            entry?.Invoke(null, null);
        }
    }
}

// OPSEC Notes for defenders:
// 1. AMSI scans Assembly.Load content before execution
// 2. ETW captures assembly load events (dotnet runtime events)
// 3. Unbacked executable memory is flagged by EDR
// 4. Process injection creates visible API call patterns
```

**Important**: Modern EDR products detect:
- `Assembly.Load` calls from suspicious processes
- Unbacked executable memory regions
- AMSI content scanning for known malicious patterns
- ETW telemetry showing anomalous assembly loading
